intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, ROUND(SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(t1.product_id), 2) AS pct_pagos_plazos FROM product_category_translation t1 JOIN products t2 ON t1.product_category_name = t2.product_category_name JOIN order_items t3 ON t2.product_id = t3.product_id JOIN order_payments t4 ON t3.order_id = t4.order_id WHERE t4.payment_type != 'not_defined' GROUP BY t1.product_category_name_english HAVING COUNT(t1.product_id) >= 100 ORDER BY pct_pagos_plazos DESC LIMIT 1"
}
